
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const LINKS={linkedin:"https://www.linkedin.com/in/abrar-ayman/",portfolio:"",behance:"",figma:"",notion:""};
$$("[data-link]").forEach(a=>{const u=LINKS[a.dataset.link];if(u)a.href=u;else{a.classList.add("off");a.removeAttribute("target");a.title="Link coming soon";a.setAttribute("aria-disabled","true")}});
$$(".lc").forEach(c=>c.addEventListener("pointermove",e=>{const r=c.getBoundingClientRect();c.style.setProperty("--mx",e.clientX-r.left+"px");c.style.setProperty("--my",e.clientY-r.top+"px")}));
const IM={"greeting": "data:image/svg+xml;base64,", "home": "data:image/svg+xml;base64,", "shop": "data:image/svg+xml;base64,", "details": "data:image/svg+xml;base64,", "profile": "data:image/svg+xml;base64,"};
const K=[["greeting", "Make a warm, confident first impression with one clear promise."], ["home", "Several entry points: search, categories and the quiz for users with different intent."], ["shop", "Browse and filter so a large catalog never becomes overload."], ["details", "Suitability, care summary and total price in one place: \u201cis this right for me?\u201d"], ["profile", "One hub for orders, wishlist, addresses and settings."]],KS=K.map(k=>k[0]);
const mk=el=>{el.innerHTML=KS.map((k,j)=>`<div class="sc${j?"":" on"}"><img src="${IM[k]}" alt="Nabta ${k} screen"></div>`).join("")};
$$("[data-s]").forEach(i=>i.src=IM[i.dataset.s]);mk($("#hscr"));mk($("#pscr"));
let hi=0;setInterval(()=>{hi=(hi+1)%K.length;$$("#hscr .sc").forEach((e,j)=>e.classList.toggle("on",j==hi))},3200);
let cur=0;const go=i=>{cur=(i+K.length)%K.length;$$("#tabs button").forEach((x,j)=>x.classList.toggle("on",j==cur));$$("#pscr .sc").forEach((x,j)=>x.classList.toggle("on",j==cur));$("#note").innerHTML="<small>Design decision</small>"+K[cur][1];$("#cnt").textContent=(cur+1)+" / "+K.length+" · swipe, tap or use dots";$$("#dots i").forEach((d,j)=>d.classList.toggle("on",j==cur))};
$("#dots").innerHTML=K.map(()=>"<i></i>").join("");go(0);$("#tabs").onclick=e=>{const b=e.target.closest("button");if(b){go($$("#tabs button").indexOf(b));rs()}};
let ap,sx=0,sw=0;const rs=()=>{clearInterval(ap);ap=setInterval(()=>go(cur+1),4500)};rs();
$("#dots").onclick=e=>{const i=$$("#dots i").indexOf(e.target);if(i>-1){go(i);rs()}};
const pp=$("#pp");pp.addEventListener("pointerdown",e=>{sx=e.clientX;sw=0});pp.addEventListener("pointerup",e=>{const d=e.clientX-sx;if(Math.abs(d)>40){sw=1;go(cur+(d<0?1:-1));rs()}});
pp.onclick=()=>{if(sw){sw=0;return}go(cur+1);rs()};$(".pv").addEventListener("pointerenter",()=>clearInterval(ap));$(".pv").addEventListener("pointerleave",rs);
$("#pp").onkeydown=e=>{if(e.key=="Enter"||e.key==" "||e.key=="ArrowRight"){e.preventDefault();go(cur+1)}if(e.key=="ArrowLeft")go(cur-1)};
const so=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting)$$("nav ul a").forEach(a=>a.classList.toggle("on",a.getAttribute("href")=="#"+e.target.id))}),{rootMargin:"-45% 0px -50% 0px"});$$("section[id]").forEach(s=>so.observe(s));
// tilt
[['#hs','#hp'],['#product .pv','#pp']].forEach(([a,b])=>{const A=$(a),B=$(b);A.addEventListener('pointermove',e=>{const r=A.getBoundingClientRect(),x=(e.clientX-r.left)/r.width-.5,y=(e.clientY-r.top)/r.height-.5;B.style.transform=`rotateY(${x*16}deg) rotateX(${-y*10}deg)`});A.addEventListener('pointerleave',()=>B.style.transform='')});
// reveal, counters
const io=new IntersectionObserver(es=>es.forEach(e=>{if(!e.isIntersecting)return;const t=e.target;t.classList.add('in');$$('[data-n]').forEach(n=>{if(t.contains(n)&&!n.d){n.d=1;const v=+n.dataset.n;let k=0;const id=setInterval(()=>{k+=.04;n.textContent=(v*Math.min(k,1)).toFixed(v%1?1:0)+(n.dataset.s||'');if(k>=1)clearInterval(id)},28)}});if(t.dataset.n){}io.unobserve(t)}),{threshold:.12});
$$('.rv,.str').forEach(e=>io.observe(e));
// lifecycle
const L=$$('#life span');let li=0;setInterval(()=>{L.forEach((s,i)=>s.classList.toggle('on',i==li));li=(li+1)%L.length},1000);
// progress
const sp=()=>{$('#bar').style.width=scrollY/(document.body.scrollHeight-innerHeight)*100+'%'};addEventListener('scroll',sp,{passive:true});
// swatches
const P=[['Forest Green','#2E7D32','#fff'],['Leaf Green','#66BB6A','#1F2937'],['Soft Sage','#DCEFD9','#1F2937'],['Warm White','#FAFAF7','#1F2937'],['Charcoal','#1F2937','#fff'],['Muted Gold','#F9A825','#1F2937'],['Terracotta Red','#D32F2F','#fff'],['Info Blue','#0288D1','#fff']];
$('#sw').innerHTML=P.map(([n,h,t])=>`<button style="background:${h};color:${t}" data-h="${h}"><b>${n}</b><span>${h}</span></button>`).join('');
$('#sw').onclick=e=>{const b=e.target.closest('button');if(!b)return;try{navigator.clipboard.writeText(b.dataset.h)}catch(_){}const s=b.lastChild;s.textContent='Copied';setTimeout(()=>s.textContent=b.dataset.h,1100)};
